336	interface ParsedOptions {
337	  devices: string[];
338	  from?: number;
339	  to?: number;
340	  tz?: string;
341	  maxInterval?: number;
342	}
343	
344	/** 解析最大采样间隔限制(正整数秒数);无效返回 null。 */
345	function parseMaxInterval(raw: string): number | null {
346	  const v = raw.trim();
347	  if (!/^\d+$/.test(v)) return null;
348	  const n = Number(v);
349	  if (!Number.isSafeInteger(n) || n < 1) return null;
350	  return n;
351	}
352	
353	/** 解析 --device/--from/--to(及允许时的 --tz、--max-interval)选项;出错返回错误消息字符串。 */
354	function parseOptions(rest: string[], allowTz = false, allowMaxInterval = false): ParsedOptions | string {
355	  const devices: string[] = [];
356	  let from: number | undefined;
357	  let to: number | undefined;
358	  let tz: string | undefined;
359	  let maxInterval: number | undefined;
360	  for (let i = 0; i < rest.length; i++) {
361	    let opt = rest[i];
362	    let value: string | undefined;
363	    const eq = opt.indexOf('=');
364	    if (opt.startsWith('--') && eq !== -1) {
365	      value = opt.slice(eq + 1);
366	      opt = opt.slice(0, eq);
367	    } else if (opt.startsWith('--')) {
368	      value = rest[i + 1];
369	      if (value === undefined) return `选项 '${opt}' 缺少值`;
370	      i++;
371	    } else {
372	      return `无法识别的参数 '${opt}'`;
373	    }
374	    if (opt === '--device') {
375	      if (value.trim() === '') return "'--device' 的值不能为空";
376	      devices.push(value);
377	    } else if (opt === '--from' || opt === '--to') {
378	      const ts = parseIso8601(value.trim());
379	      if (ts === null) {
380	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
381	      }
382	      if (opt === '--from') from = ts;
383	      else to = ts;
384	    } else if (opt === '--tz' && allowTz) {
385	      tz = value.trim();
386	      if (tz === '') return "'--tz' 的值不能为空";
387	    } else if (opt === '--max-interval' && allowMaxInterval) {
388	      const n = parseMaxInterval(value);
389	      if (n === null) {
390	        return `选项 '--max-interval' 的值无效: '${value.trim()}'(需正整数秒数)`;
391	      }
392	      maxInterval = n;
393	    } else {
394	      return `无法识别的选项 '${opt}'`;
395	    }
396	  }
397	  return { devices, from, to, tz, maxInterval };
398	}
399	
400	/** 校验 IANA 分日时区名;无效时返回错误消息字符串。 */
401	function checkTz(tz: string): string | null {
402	  if (loadTimezone(tz) === null) {
403	    return `未知时区 '${tz}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`;
404	  }
405	  return null;
406	}
407	
408	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
409	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
410	  const out = new Map<string, string[]>();
411	  for (let i = 0; i < rest.length; i++) {
412	    let opt = rest[i];
413	    let value: string | undefined;
414	    const eq = opt.indexOf('=');
415	    if (opt.startsWith('--') && eq !== -1) {
416	      value = opt.slice(eq + 1);
417	      opt = opt.slice(0, eq);
418	    } else if (opt.startsWith('--')) {
419	      value = rest[i + 1];
420	      if (value === undefined) return `选项 '${opt}' 缺少值`;
421	      i++;
422	    } else {
423	      return `无法识别的参数 '${opt}'`;
424	    }
425	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
426	    const list = out.get(opt);
427	    if (list) list.push(value);
428	    else out.set(opt, [value]);
429	  }
430	  return out;
431	}
432	
433	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
434	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
435	  const list = flags.get(name);
436	  if (!list || list.length !== 1) return null;
437	  return list[0];
438	}
439	
440	/** 解析 YYYY-MM-DD 日期选项为当地日期标签;无效时返回错误消息字符串。 */
441	function dateFlag(value: string, label: string): { date: string } | string {
442	  const v = value.trim();
443	  if (parseUtcDate(v) === null) {
444	    return `${label}无效: '${v}'(需 YYYY-MM-DD 的真实日期)`;
445	  }
446	  return { date: v };
447	}
448	
449	function cmdRule(rest: string[]): number {
450	  const [sub, ...subrest] = rest;
451	  if (sub === 'list') {
452	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
453	    return cmdRuleList();
454	  }
455	  if (sub === 'create') {
456	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold', '--tz', '--max-interval', '--schedule']);
457	    if (typeof flags === 'string') return usageError(flags);
458	    const idRaw = oneFlag(flags, '--id');
459	    const deviceList = flags.get('--device');
460	    const groupList = flags.get('--group');
461	    const thresholdRaw = oneFlag(flags, '--threshold');
462	    const tzList = flags.get('--tz');
463	    const maxIntervalList = flags.get('--max-interval');
464	    const scheduleList = flags.get('--schedule');
465	    if (idRaw === null || thresholdRaw === null) {
466	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
467	    }
468	    if (tzList !== undefined && tzList.length !== 1) {
469	      return usageError("'rule create' 的 --tz 只能出现一次");
470	    }
471	    if (maxIntervalList !== undefined && maxIntervalList.length !== 1) {
472	      return usageError("'rule create' 的 --max-interval 只能出现一次");
473	    }
474	    if (scheduleList !== undefined && scheduleList.length !== 1) {
475	      return usageError("'rule create' 的 --schedule 只能出现一次");
476	    }
477	    const hasDevice = deviceList !== undefined;
478	    const hasGroup = groupList !== undefined;
479	    if (hasDevice === hasGroup) {
480	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
481	    }
482	    if ((deviceList !== undefined && deviceList.length !== 1) ||
483	      (groupList !== undefined && groupList.length !== 1)) {
484	      return usageError("'rule create' 的目标选项只能出现一次");
485	    }
486	    const id = idRaw.trim();
487	    if (id === '') return usageError('规则标识不能为空');
488	    const thresholdMilli = parseKwh(thresholdRaw.trim());
489	    if (thresholdMilli === null) {
490	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
491	    }
492	    // 时区省略与显式 UTC 等价;按运行环境解析后的规范名存储与比较。
493	    let tz = 'UTC';
494	    if (tzList !== undefined) {
495	      const tzRaw = tzList[0].trim();
496	      if (tzRaw === '') return usageError("'--tz' 的值不能为空");
497	      const canonical = canonicalTimezone(tzRaw);
498	      if (canonical === null) {
499	        return usageError(`未知时区 '${tzRaw}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`);
