741	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
742	  const segments: string[][] = [[]];
743	  for (const tok of rest) {
744	    if (tok === '--item') segments.push([]);
745	    else segments[segments.length - 1].push(tok);
746	  }
747	  const headFlags = parseFlags(segments[0], ['--request']);
748	  if (typeof headFlags === 'string') return headFlags;
749	  const requestRaw = oneFlag(headFlags, '--request');
750	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
751	  const requestId = requestRaw.trim();
752	  if (requestId === '') return '请求标识不能为空';
753	  const itemSegs = segments.slice(1);
754	  if (itemSegs.length === 0) {
755	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
756	  }
757	  const items: CorrectionItem[] = [];
758	  for (const seg of itemSegs) {
759	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
760	    if (typeof flags === 'string') return flags;
761	    const deviceRaw = oneFlag(flags, '--device');
762	    const atRaw = oneFlag(flags, '--at');
763	    const expectRaw = oneFlag(flags, '--expect');
764	    const setRaw = oneFlag(flags, '--set');
765	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
766	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
767	    }
768	    const device = deviceRaw.trim();
769	    if (device === '') return "'--device' 的值不能为空";
770	    const ts = parseIso8601(atRaw.trim());
771	    if (ts === null) {
772	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
773	    }
774	    const expectedMilli = parseKwh(expectRaw.trim());
775	    if (expectedMilli === null) {
776	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
777	    }
778	    const replacementMilli = parseKwh(setRaw.trim());
779	    if (replacementMilli === null) {
780	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
781	    }
782	    items.push({ device, ts, expectedMilli, replacementMilli });
783	  }
784	  return { requestId, items };
