808	function main(args: string[]): number {
809	  // 救援入口单独协调:先取得目录操作权并续接上次被中断的救援,但绝不续接
810	  // 旧 restore 事务——那正是救援要留存并放弃的对象;恢复日志损坏不再阻塞
811	  // 救援入口。其余所有入口(含无参数、--help/-h、非法参数)都先完成启动
812	  // 自恢复协调,再执行查询或写入;协调失败返回 1,不输出正常业务结果。
813	  const [cmd, ...rest] = args;
814	  if (cmd === 'rescue') {
815	    const result = withRescueCoordination<number>(() => {
816	      if (rest.length !== 1) {
817	        return usageError("'rescue' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
818	      }
819	      return cmdRescue(rest[0]);
820	    });
821	    return typeof result === 'number' ? result : 1;
822	  }
823	  const result = withDirectoryCoordination<number>(() => runCommand(args));
824	  return typeof result === 'number' ? result : 1;
825	}
826	
827	function runCommand(args: string[]): number {
828	  if (args.length === 0) {
829	    console.log(help);
830	    return 0;
831	  }
832	  const [cmd, ...rest] = args;
833	  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
834	    console.log(help);
835	    return 0;
836	  }
837	
838	  if (cmd === 'import') {
839	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
840	    return cmdImport(rest[0]);
841	  }
842	
843	  if (cmd === 'readings') {
844	    const parsed = parseOptions(rest);
845	    if (typeof parsed === 'string') return usageError(parsed);
846	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
847	      return usageError('查询起点必须早于终点(--from < --to)');
848	    }
849	    return cmdReadings(parsed);
850	  }
851	
852	  if (cmd === 'daily') {
853	    const parsed = parseOptions(rest, true, true);
854	    if (typeof parsed === 'string') return usageError(parsed);
855	    if (parsed.from === undefined || parsed.to === undefined) {
856	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
857	    }
858	    if (parsed.from >= parsed.to) {
859	      return usageError('查询起点必须早于终点(--from < --to)');
860	    }
861	    if (parsed.tz !== undefined) {
862	      const bad = checkTz(parsed.tz);
863	      if (bad !== null) return usageError(bad);
864	    }
865	    return cmdDaily({
866	      devices: parsed.devices,
867	      from: parsed.from,
868	      to: parsed.to,
869	      tz: parsed.tz,
870	      maxInterval: parsed.maxInterval,
871	    });
872	  }
873	
874	  if (cmd === 'rule') return cmdRule(rest);
875	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
876	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
877	  if (cmd === 'group') return cmdGroup(rest);
878	  if (cmd === 'correct') return cmdCorrectEntry(rest);
879	  if (cmd === 'undo') return cmdUndoEntry(rest);
880	
881	  if (cmd === 'corrections') {
882	    if (rest.length !== 0) return usageError("'corrections' 不接受参数");
883	    return cmdCorrections();
884	  }
885	
886	  if (cmd === 'ack') {
887	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
888	    const alertId = rest[0].trim();
889	    if (alertId === '') return usageError('告警标识不能为空');
890	    return cmdAck(alertId);
891	  }
892	
893	  if (cmd === 'backup') {
894	    if (rest.length !== 1) return usageError("'backup' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
895	    return cmdBackup(rest[0]);
896	  }
897	
898	  if (cmd === 'restore') {
899	    if (rest.length !== 1) return usageError("'restore' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
900	    return cmdRestore(rest[0]);
901	  }
902	
903	  return usageError(`无法识别的参数 '${cmd}'`);
904	}
