159	  for (const r of alerts.rules) {
160	    if (r.targetType === 'device' && !devices.has(r.targetId)) {
161	      problems.push(`rule '${r.id}' targets device '${r.targetId}' which has no stored readings`);
162	    }
163	    if (r.targetType === 'group' && !groupIds.has(r.targetId)) {
164	      problems.push(`rule '${r.id}' targets unknown group '${r.targetId}'`);
165	    }
166	  }
167	
168	  // 告警必须引用已存规则。
169	  const ruleIds = new Set(alerts.rules.map((r) => r.id));
170	  for (const a of alerts.alerts) {
171	    if (!ruleIds.has(a.ruleId)) {
172	      problems.push(`alert '${a.id}' references missing rule '${a.ruleId}'`);
173	    }
174	  }
175	
176	  return problems;
177	}
178	
179	// ---------------------------------------------------------------------------
180	// 目录操作权(排他锁,按数据目录隔离)
181	// ---------------------------------------------------------------------------
182	
183	/**
184	 * 获取数据目录的排他操作权;成功返回 null,失败返回错误消息。
185	 * 锁文件已存在且属存活进程时拒绝(不读写业务存储、不清理对方事务材料);
186	 * 属已退出进程时清理后重试一次(其未完成恢复由接管方持锁续接)。
187	 */
188	function acquireLock(dir: string): string | null {
189	  const lockPath = join(dir, LOCK_NAME);
190	  for (let attempt = 0; attempt < 2; attempt++) {
191	    try {
192	      const fd = openSync(lockPath, 'wx');
193	      try {
194	        writeFileSync(fd, `${process.pid}\n`);
195	      } finally {
196	        closeSync(fd);
197	      }
198	      return null;
199	    } catch (e) {
200	      const code = (e as NodeJS.ErrnoException).code;
201	      if (code !== 'EEXIST') {
202	        return `cannot acquire directory lock ${lockPath}: ${(e as Error).message}`;
203	      }
204	      let pid = Number.NaN;
205	      try {
206	        pid = Number(readFileSync(lockPath, 'utf8').trim());
207	      } catch {
208	        // 读不出属主按存活处理,不冒险清理。
209	      }
210	      let alive = true;
211	      if (Number.isInteger(pid) && pid > 0) {
212	        try {
213	          process.kill(pid, 0);
214	        } catch (ke) {
215	          alive = (ke as NodeJS.ErrnoException).code === 'EPERM';
216	        }
217	      }
218	      if (alive) {
219	        return (
220	          `data directory ${dir} is locked by another live meterwatch process` +
221	          `${Number.isInteger(pid) && pid > 0 ? ` (pid ${pid})` : ''}; ` +
222	          `wait for it to finish, or use another data directory`
223	        );
224	      }
225	      try {
226	        rmSync(lockPath);
227	      } catch (re) {
228	        return `cannot remove stale lock ${lockPath}: ${(re as Error).message}`;
229	      }
230	    }
231	  }
232	  return `cannot acquire directory lock ${join(dir, LOCK_NAME)}`;
233	}
234	
235	function releaseLock(dir: string): void {
236	  try {
237	    rmSync(join(dir, LOCK_NAME));
238	  } catch {
239	    // 锁文件可能已被清理;释放失败不影响已完成的操作。
240	  }
241	}
242	
243	/** 目标是否为常规文件;路径不存在返回 false,其他类型(目录等)返回 false。 */
244	function isRegularFile(p: string): boolean {
245	  try {
246	    return statSync(p).isFile();
247	  } catch {
248	    return false;
249	  }
250	}
251	
252	// ---------------------------------------------------------------------------
253	// 恢复日志
254	// ---------------------------------------------------------------------------
255	
256	interface JournalFile {
257	  /** 业务存储文件名(basename)。 */
258	  name: string;
259	  /** 恢复前该文件是否存在(原本缺失的,回滚后必须仍为缺失)。 */
260	  hadOld: boolean;
261	}
262	
263	interface Journal {
264	  phase: RestorePhase;
265	  files: JournalFile[];
266	}
267	
268	/**
269	 * 解析恢复日志。结构非法返回 null:调用方按无法可靠判定处理,绝不猜测,
270	 * 也不清理仍可用于恢复的材料。
271	 */
272	function parseJournal(data: unknown): Journal | null {
273	  const o = data as Record<string, unknown>;
274	  if (
275	    o === null ||
276	    typeof o !== 'object' ||
277	    o.format !== JOURNAL_FORMAT ||
278	    o.version !== 1 ||
279	    !Array.isArray(o.files) ||
280	    o.files.length === 0
281	  ) {
282	    return null;
283	  }
284	  // 旧日志缺失阶段字段时按最保守的 committing 处理(只能前滚);但显式写出
285	  // 的未知阶段无法可靠判定方向,按无效日志处理——保留材料,绝不猜测。
286	  let phase: RestorePhase = 'committing';
287	  if (o.phase !== undefined) {
288	    if (typeof o.phase !== 'string' || !(PHASES as string[]).includes(o.phase)) {
289	      return null;
290	    }
291	    phase = o.phase as RestorePhase;
292	  }
293	  const names = new Set<string>();
294	  const files: JournalFile[] = [];
295	  for (const f of o.files as Array<Record<string, unknown>>) {
296	    if (
297	      f === null ||
298	      typeof f !== 'object' ||
299	      typeof f.name !== 'string' ||
300	      f.name.length === 0 ||
301	      basename(f.name as string) !== f.name ||
302	      typeof f.hadOld !== 'boolean' ||
303	      names.has(f.name as string)
304	    ) {
305	      return null;
306	    }
307	    names.add(f.name as string);
308	    files.push({ name: f.name as string, hadOld: f.hadOld as boolean });
309	  }
310	  return { phase, files };
311	}
312	
313	/** 原子改写日志阶段(先写临时文件再换名)。失败抛错,材料保留。 */
314	function writeJournalPhase(dir: string, journal: Journal, phase: RestorePhase): void {
315	  const journalPath = join(dir, JOURNAL_NAME);
316	  const tmp = `${journalPath}.tmp-${process.pid}`;
317	  writeFileSync(
318	    tmp,
319	    JSON.stringify(
320	      { format: JOURNAL_FORMAT, version: 1, phase, files: journal.files },
321	      null,
322	      2,
323	    ) + '\n',
324	    'utf8',
325	  );
326	  renameSync(tmp, journalPath);
327	  journal.phase = phase;
328	}
329	
330	// ---------------------------------------------------------------------------
331	// 回滚(还原完整旧库)——幂等,可跨中断续接
332	// ---------------------------------------------------------------------------
333	
334	/**
335	 * 回滚到恢复前状态。必须在 journal.phase === 'rolling-back' 下调用。
336	 *
337	 * 幂等且可在任意一步中断后续接:
338	 * - 旧文件备份存在:原位若为常规文件则删除,再把备份原子换回(rename 覆盖
339	 *   已先删除,故不会因 EEXIST 失败);已还原到原位的旧文件不会被误删。
340	 * - 原本缺失(hadOld=false):旧备份按定义不存在;删除事务换入的新内容,
341	 *   恢复为缺失。原位不存在时即为已完成,绝不把缺文件当成空库而补写。
342	 * - hadOld=true 但原位与旧备份同时缺失:状态被外部破坏,无法可靠还原,
343	 *   抛错并保留全部材料,不猜测。
344	 * 旧备份与待换入新内容必须是常规文件,否则按被篡改处理,中止回滚。
345	 */
346	function rollbackPass(dir: string, journal: Journal): void {
347	  for (const f of journal.files) {
348	    const target = join(dir, f.name);
349	    const oldPath = target + OLD_SUFFIX;
350	    const newPath = target + NEW_SUFFIX;
351	    if (isRegularFile(oldPath)) {
352	      // hadOld=false 的文件按定义从不产生旧备份;若出现则与日志矛盾,不据此
353	      // 复活内容(否则会把事务造成的缺文件错误还原成某个来历不明的文件)。
354	      if (!f.hadOld) {
355	        throw new StoreError(`cannot roll back ${target}: backup exists but the journal records no original file`);
356	      }
357	      if (existsSync(target)) {
358	        if (!isRegularFile(target)) {
359	          throw new StoreError(`cannot roll back ${target}: target exists but is not a regular file`);
360	        }
361	        rmSync(target);
362	      }
363	      renameSync(oldPath, target);
364	    } else if (existsSync(oldPath)) {
365	      throw new StoreError(`restore backup ${oldPath} is not a regular file`);
366	    } else if (f.hadOld) {
367	      if (!existsSync(target)) {
368	        throw new StoreError(`cannot roll back ${target}: both the original and its backup are missing`);
369	      }
370	      if (!isRegularFile(target)) {
371	        throw new StoreError(`cannot roll back ${target}: restored original is not a regular file`);
372	      }
373	      // 原位已是常规文件:上一轮已还原完成,保持不动(绝不误删)。
374	    } else {
375	      // 原本缺失:清除事务换入的内容(原位或残留新临时文件),恢复为缺失。
376	      if (existsSync(newPath)) {
377	        if (!isRegularFile(newPath)) {
378	          throw new StoreError(`restore temp file ${newPath} is not a regular file`);
379	        }
380	        rmSync(newPath);
381	      }
382	      if (existsSync(target)) {
383	        if (!isRegularFile(target)) {
384	          throw new StoreError(`cannot restore missing state for ${target}: target is not a regular file`);
385	        }
386	        rmSync(target);
387	      }
388	    }
389	  }
390	}
391	
392	/** 回滚收尾:删除残留新临时文件,再删日志。旧文件备份已全部换回原位。 */
393	function rollbackCleanup(dir: string, journal: Journal): void {
394	  for (const f of journal.files) {
395	    const newPath = join(dir, f.name) + NEW_SUFFIX;
396	    if (existsSync(newPath)) {
397	      // 该名字属于本次事务的临时命名空间;正常产物必为常规文件。即便是异常
398	      // 占位(如目录),也随回滚一并递归清除,不影响业务存储。
399	      rmSync(newPath, { recursive: true, force: true });
400	    }
401	    const oldPath = join(dir, f.name) + OLD_SUFFIX;
402	    if (existsSync(oldPath)) {
403	      // 正常不应残留;若仍在则回滚未完成,保留材料并报错,不删日志。
404	      throw new StoreError(`restore backup ${oldPath} was not restored; rollback is incomplete`);
405	    }
406	  }
407	  rmSync(join(dir, JOURNAL_NAME));
408	}
409	
410	// ---------------------------------------------------------------------------
411	// 前滚(提交完整快照)——幂等,可跨中断续接
412	// ---------------------------------------------------------------------------
413	
414	/**
415	 * 前滚到完整快照状态,逐文件幂等,可在任意一步中断后续接。每个文件只有崩溃
416	 * 可达的三种状态:
417	 *   未动:原位=旧内容(hadOld 时)或原位缺失,新临时在,旧备份无;
418	 *   旧已移走:原位缺失,新临时在,旧备份在;
419	 *   已换入:原位=新内容,新临时无,旧备份在(hadOld 时);原本缺失的文件
420	 *           (hadOld=false)已换入时旧备份按定义不存在。
421	 * 判据:新临时还在就说明该文件尚未换入——原位若有旧内容先移为旧备份,再把
422	 * 新临时换入;新临时不在则原位必须已是常规文件。关键不变量:日志仍在时
423	 * 收尾尚未运行(收尾先删日志再删旧备份),故 hadOld 的已换入文件必仍带旧
424	 * 备份;原位是常规内容、新临时与旧备份却都不在属于无法可靠判定的状态,
425	 * 直接抛错并保留材料,绝不把旧内容误当新内容而提交混合状态。
426	 */
427	function rollForwardPass(dir: string, journal: Journal): void {
428	  for (const f of journal.files) {
429	    const target = join(dir, f.name);
430	    const newPath = target + NEW_SUFFIX;
431	    const oldPath = target + OLD_SUFFIX;
432	    if (existsSync(newPath)) {
433	      if (!isRegularFile(newPath)) {
434	        throw new StoreError(`restore temp file ${newPath} is not a regular file`);
435	      }
436	      if (existsSync(target)) {
437	        // 旧内容仍在原位,先移为备份。
438	        if (!isRegularFile(target)) {
439	          throw new StoreError(`cannot commit ${target}: target exists but is not a regular file`);
440	        }
441	        if (existsSync(oldPath)) {
442	          throw new StoreError(`cannot commit ${target}: both the original and its backup are present`);
443	        }
444	        if (!f.hadOld) {
445	          // 日志称原本缺失,原位却有内容:与日志矛盾,不猜测。
446	          throw new StoreError(`cannot commit ${target}: journal says it was originally absent`);
447	        }
448	        renameSync(target, oldPath);
449	      }
450	      renameSync(newPath, target);
451	    } else if (isRegularFile(target)) {
452	      // 新临时已不在:视为已换入。hadOld 的文件此刻必仍有旧备份(日志还在,
453	      // 收尾未运行);缺失则状态无法可靠判定,中止而不猜。
454	      if (f.hadOld && !existsSync(oldPath)) {
455	        throw new StoreError(
456	          `cannot determine state of ${target}: neither its restore temp nor its backup exists`,
457	        );
458	      }
459	    } else {
460	      throw new StoreError(`cannot commit ${target}: business store is missing or not a regular file`);
461	    }
462	  }
463	  for (const f of journal.files) {
464	    if (!isRegularFile(join(dir, f.name))) {
465	      throw new StoreError(`cannot commit ${join(dir, f.name)}: business store is missing or not a regular file`);
466	    }
467	  }
468	}
469	
470	/** 前滚收尾:删除日志与旧文件备份(新临时文件已全部换入)。 */
471	function rollForwardCleanup(dir: string, journal: Journal): void {
472	  for (const f of journal.files) {
473	    const newPath = join(dir, f.name) + NEW_SUFFIX;
474	    if (existsSync(newPath)) {
475	      throw new StoreError(`restore temp file ${newPath} still present; commit is incomplete`);
476	    }
477	  }
478	  rmSync(join(dir, JOURNAL_NAME));
479	  for (const f of journal.files) {
480	    const oldPath = join(dir, f.name) + OLD_SUFFIX;
481	    if (existsSync(oldPath)) rmSync(oldPath);
482	  }
483	}
484	
485	// ---------------------------------------------------------------------------
486	// 显式快照救援(rescue):放弃无法可靠续接的旧事务,留存原始材料后整库替换
487	// ---------------------------------------------------------------------------
488	
489	/** 救援阶段;确定回退(rolling-back)后不得改向。 */
490	type RescuePhase = 'preserving' | 'committing' | 'rolling-back' | 'done';
491	const RESCUE_PHASES: RescuePhase[] = ['preserving', 'committing', 'rolling-back', 'done'];
492	
493	interface RescueJournal {
494	  phase: RescuePhase;
495	  /** 留存目录名(basename,位于数据目录内)。 */
496	  preservedDir: string;
497	  /** 三个业务存储文件名(basename,顺序固定)。 */
498	  stores: string[];
499	  /** 固定名字集的留存记录:救援前每个名字是否存在(原始字节在留存目录内)。 */
500	  preserved: Array<{ name: string; hadOld: boolean }>;
501	}
502	
503	/**
504	 * 救援留存固定覆盖的名字:三个业务存储、restore.journal 及对应
505	 * *.restore-old/*.restore-new。绝不依据(可能损坏的)旧日志里的文件名操作。
506	 */
507	function preservedNames(): string[] {
508	  const names: string[] = [];
509	  for (const path of storeFiles()) {
510	    const name = basename(path);
511	    names.push(name, name + OLD_SUFFIX, name + NEW_SUFFIX);
512	  }
513	  names.push(JOURNAL_NAME);
514	  return names;
515	}
516	
517	/**
518	 * 解析救援日志。结构非法或含显式未知阶段返回 null:调用方按无法可靠判定
519	 * 处理,保留全部材料,绝不猜测;缺失阶段字段按最保守的 committing 处理。
520	 */
521	function parseRescueJournal(data: unknown): RescueJournal | null {
522	  const o = data as Record<string, unknown>;
523	  if (
524	    o === null ||
525	    typeof o !== 'object' ||
526	    o.format !== RESCUE_JOURNAL_FORMAT ||
527	    o.version !== 1 ||
528	    typeof o.preservedDir !== 'string' ||
529	    o.preservedDir.length === 0 ||
530	    basename(o.preservedDir as string) !== o.preservedDir ||
531	    !Array.isArray(o.stores) ||
532	    o.stores.length === 0 ||
533	    !Array.isArray(o.preserved)
534	  ) {
535	    return null;
536	  }
537	  let phase: RescuePhase = 'committing';
538	  if (o.phase !== undefined) {
539	    if (typeof o.phase !== 'string' || !(RESCUE_PHASES as string[]).includes(o.phase)) {
540	      return null;
541	    }
542	    phase = o.phase as RescuePhase;
543	  }
544	  const stores: string[] = [];
545	  for (const s of o.stores as unknown[]) {
546	    if (typeof s !== 'string' || s.length === 0 || basename(s) !== s) return null;
547	    stores.push(s);
548	  }
549	  const seen = new Set<string>();
550	  const preserved: Array<{ name: string; hadOld: boolean }> = [];
551	  for (const f of o.preserved as Array<Record<string, unknown>>) {
552	    if (
553	      f === null ||
554	      typeof f !== 'object' ||
555	      typeof f.name !== 'string' ||
556	      f.name.length === 0 ||
557	      basename(f.name as string) !== f.name ||
558	      typeof f.hadOld !== 'boolean' ||
559	      seen.has(f.name as string)
560	    ) {
561	      return null;
562	    }
563	    seen.add(f.name as string);
564	    preserved.push({ name: f.name as string, hadOld: f.hadOld as boolean });
565	  }
566	  return { phase, preservedDir: o.preservedDir as string, stores, preserved };
567	}
568	
569	/** 原子改写救援日志阶段(先写临时文件再换名)。失败抛错,材料保留。 */
570	function writeRescueJournalPhase(dir: string, journal: RescueJournal, phase: RescuePhase): void {
571	  const journalPath = join(dir, RESCUE_JOURNAL_NAME);
572	  const tmp = `${journalPath}.tmp-${process.pid}`;
573	  writeFileSync(
574	    tmp,
575	    JSON.stringify(
576	      {
577	        format: RESCUE_JOURNAL_FORMAT,
578	        version: 1,
579	        phase,
580	        preservedDir: journal.preservedDir,
581	        stores: journal.stores,
582	        preserved: journal.preserved,
583	      },
584	      null,
585	      2,
586	    ) + '\n',
587	    'utf8',
588	  );
589	  renameSync(tmp, journalPath);
590	  journal.phase = phase;
591	}
592	
593	/** 删除救援的新内容临时文件(幂等)。 */
594	function removeRescueTemps(dir: string, stores: string[]): void {
595	  for (const name of stores) {
596	    const newPath = join(dir, name) + RESCUE_NEW_SUFFIX;
597	    if (existsSync(newPath)) rmSync(newPath);
598	  }
599	}
600	
601	/**
602	 * 救援前滚为完整快照,逐文件幂等,可在任意一步中断后续接。新临时还在则
603	 * 换入(原位内容先删除,其原始字节已在留存目录);新临时不在则原位必须
604	 * 已是常规文件,否则状态无法可靠判定,抛错并保留材料。
605	 */
606	function rescueRollForwardPass(dir: string, journal: RescueJournal): void {
607	  for (const name of journal.stores) {
608	    const target = join(dir, name);
609	    const newPath = target + RESCUE_NEW_SUFFIX;
610	    if (existsSync(newPath)) {
611	      if (!isRegularFile(newPath)) {
612	        throw new StoreError(`rescue temp file ${newPath} is not a regular file`);
613	      }
614	      if (existsSync(target)) {
615	        if (!isRegularFile(target)) {
616	          throw new StoreError(`cannot commit ${target}: target exists but is not a regular file`);
617	        }
618	        rmSync(target);
619	      }
620	      renameSync(newPath, target);
621	    } else if (!isRegularFile(target)) {
622	      throw new StoreError(`cannot commit ${target}: business store is missing or not a regular file`);
623	    }
624	  }
625	}
626	
627	/**
628	 * 救援提交收尾:旧事务材料(restore.journal、*.restore-old、*.restore-new)
629	 * 的原始字节已持久留存,从活动位置移除(救援即放弃旧事务);最后删除救援
630	 * 日志。幂等,中断后由启动续接重跑。留存目录绝不触碰。
631	 */
632	function rescueCommitCleanup(dir: string, journal: RescueJournal): void {
633	  for (const name of journal.stores) {
634	    const newPath = join(dir, name) + RESCUE_NEW_SUFFIX;
635	    if (existsSync(newPath)) {
636	      throw new StoreError(`rescue temp file ${newPath} still present; commit is incomplete`);
637	    }
638	  }
639	  for (const entry of journal.preserved) {
640	    if (entry.name === JOURNAL_NAME || entry.name.endsWith(OLD_SUFFIX) || entry.name.endsWith(NEW_SUFFIX)) {
641	      const p = join(dir, entry.name);
642	      if (existsSync(p)) rmSync(p);
643	    }
644	  }
645	  rmSync(join(dir, RESCUE_JOURNAL_NAME));
646	}
647	
648	/**
649	 * 救援回滚:按留存记录还原救援前三个业务文件与旧事务材料的内容与存在状态,
650	 * 逐条幂等,可在任意一步中断后续接。留存字节缺失或与记录矛盾时抛错并保留
651	 * 全部材料,不猜测。
652	 */
653	function rescueRollbackPass(dir: string, journal: RescueJournal): void {
654	  const preservedDir = join(dir, journal.preservedDir);
655	  for (const entry of journal.preserved) {
656	    const live = join(dir, entry.name);
657	    const kept = join(preservedDir, entry.name);
658	    if (entry.hadOld) {
659	      if (!isRegularFile(kept)) {
660	        throw new StoreError(
661	          `cannot restore pre-rescue ${live}: preserved copy ${kept} is missing or not a regular file`,
662	        );
663	      }
664	      if (existsSync(live)) {
665	        if (!isRegularFile(live)) {
666	          throw new StoreError(`cannot restore pre-rescue ${live}: live path exists but is not a regular file`);
667	        }
668	        rmSync(live);
669	      }
670	      copyFileSync(kept, live);
671	    } else {
672	      if (existsSync(kept)) {
673	        throw new StoreError(
674	          `cannot restore pre-rescue ${live}: preserved copy ${kept} exists but the rescue journal records it was absent`,
675	        );
676	      }
677	      if (existsSync(live)) {
678	        if (!isRegularFile(live)) {
679	          throw new StoreError(`cannot restore missing state for ${live}: live path is not a regular file`);
680	        }
681	        rmSync(live);
682	      }
683	    }
684	  }
685	}
686	
687	/** 救援回滚收尾:删除新临时文件与救援日志。留存目录保留,不自动清理。 */
688	function rescueRollbackCleanup(dir: string, journal: RescueJournal): void {
689	  removeRescueTemps(dir, journal.stores);
690	  rmSync(join(dir, RESCUE_JOURNAL_NAME));
691	}
692	
693	/**
694	 * 续接被中断的救援(持锁调用)。依据救援日志阶段决定方向:
695	 * - preserving:替换尚未开始,退回救援前状态(删新临时与救援日志,留存保留)。
696	 * - committing/done:只能前滚为完整快照。
697	 * - rolling-back:只能继续还原救援前状态,不得改向。
698	 * 无救援日志时清理可能残留的救援临时文件。成功(或无需续接)返回 null;
699	 * 无法可靠判定或完成时返回错误消息,材料一律保留。
700	 */
701	function continueInterruptedRescue(dir: string): string | null {
702	  const journalPath = join(dir, RESCUE_JOURNAL_NAME);
703	  if (!existsSync(journalPath)) {
704	    // 无救援日志:替换未开始(残留新临时文件)或已完整完成。这些残留不属于
705	    // 任何活动救援,清理即可;清理失败明确报错,不继续启动。
706	    for (const path of storeFiles()) {
707	      const leftover = path + RESCUE_NEW_SUFFIX;
708	      if (existsSync(leftover)) {
709	        try {
710	          rmSync(leftover);
711	        } catch (e) {
712	          return `cannot clean up interrupted rescue leftover ${leftover}: ${(e as Error).message}`;
713	        }
714	      }
715	    }
716	    for (const entry of readdirSync(dir)) {
717	      if (entry.startsWith(`${RESCUE_JOURNAL_NAME}.tmp-`)) {
718	        try {
719	          rmSync(join(dir, entry));
720	        } catch (e) {
721	          return `cannot clean up interrupted rescue leftover ${join(dir, entry)}: ${(e as Error).message}`;
722	        }
723	      }
724	    }
725	    return null;
726	  }
727	  let journal: RescueJournal | null = null;
728	  try {
729	    journal = parseRescueJournal(JSON.parse(readFileSync(journalPath, 'utf8')));
730	  } catch {
731	    journal = null;
732	  }
733	  if (journal === null) {
734	    return (
735	      `cannot recover data directory ${dir}: rescue journal ${journalPath} is unreadable or invalid; ` +
736	      `the directory may hold rescue materials in an unknown state - nothing was deleted; ` +
737	      `inspect ${RESCUE_JOURNAL_NAME} and '${PRESERVED_PREFIX}*' before retrying`
738	    );
739	  }
740	  try {
741	    if (journal.phase === 'preserving') {
742	      removeRescueTemps(dir, journal.stores);
743	      rmSync(journalPath);
744	      err('abandoned an interrupted rescue before any replacement: pre-rescue state kept');
745	      return null;
746	    }
747	    if (journal.phase === 'committing' || journal.phase === 'done') {
748	      if (journal.phase === 'committing') {
749	        rescueRollForwardPass(dir, journal);
750	        writeRescueJournalPhase(dir, journal, 'done');
751	      }
752	      rescueCommitCleanup(dir, journal);
753	      err('completed an interrupted rescue: snapshot state committed');
754	      return null;
755	    }
756	    // rolling-back:确定回退后只能继续还原救援前状态。
757	    rescueRollbackPass(dir, journal);
758	    rescueRollbackCleanup(dir, journal);
759	    err('continued an interrupted rescue rollback: pre-rescue state restored');
760	    return null;
761	  } catch (e) {
762	    return (
763	      `cannot complete interrupted rescue for data directory ${dir}: ${(e as Error).message}; ` +
764	      `rescue materials were kept (${RESCUE_JOURNAL_NAME}, '${PRESERVED_PREFIX}*', ` +
765	      `'*${RESCUE_NEW_SUFFIX}'); resolve the underlying read/write problem and run any ` +
766	      `meterwatch command again`
767	    );
768	  }
769	}
