1016	// ---------------------------------------------------------------------------
1017	// 目录操作权 + 自恢复:所有命令的统一入口协调
1018	// ---------------------------------------------------------------------------
1019	
1020	/**
1021	 * 取得数据目录的排他操作权并先处理未完成恢复,然后运行业务动作。
1022	 *
1023	 * 任何命令(含无参数、--help/-h 与非法参数入口)都必须先完成本协调:
1024	 * - 目录不存在则创建(数据目录本身可由本工具建立);
1025	 * - 锁被存活进程占用:返回 1,不读写业务存储、不清理对方事务材料;
1026	 * - 自恢复无法可靠完成:返回 1,不运行业务动作;
1027	 * - 成功后运行业务动作并沿用其退出码,释放锁。
1028	 */
1029	export function withDirectoryCoordination<T>(action: () => T): T | number {
1030	  const dir = dataDirPath();
1031	  try {
1032	    mkdirSync(dir, { recursive: true });
1033	  } catch (e) {
1034	    err(`cannot access data directory ${dir}: ${(e as Error).message}`);
1035	    return 1;
1036	  }
1037	  const lockError = acquireLock(dir);
1038	  if (lockError !== null) {
1039	    err(lockError);
1040	    return 1;
1041	  }
1042	  try {
1043	    const recoveryError = recoverIfNeeded(dir);
1044	    if (recoveryError !== null) {
1045	      err(recoveryError);
1046	      return 1;
1047	    }
1048	    return action();
1049	  } finally {
1050	    releaseLock(dir);
1051	  }
1052	}
1053	
1054	/**
1055	 * 救援入口的目录协调:取得排他操作权并续接上次被中断的救援,然后运行
1056	 * 救援动作。与 withDirectoryCoordination 的唯一区别是不续接旧 restore
1057	 * 事务——那正是救援要留存并放弃的对象;恢复日志损坏不再阻塞入口。
1058	 */
1059	export function withRescueCoordination<T>(action: () => T): T | number {
1060	  const dir = dataDirPath();
1061	  try {
1062	    mkdirSync(dir, { recursive: true });
1063	  } catch (e) {
1064	    err(`cannot access data directory ${dir}: ${(e as Error).message}`);
1065	    return 1;
1066	  }
1067	  const lockError = acquireLock(dir);
1068	  if (lockError !== null) {
1069	    err(lockError);
1070	    return 1;
1071	  }
1072	  try {
1073	    const rescueError = continueInterruptedRescue(dir);
1074	    if (rescueError !== null) {
1075	      err(rescueError);
1076	      return 1;
1077	    }
1078	    return action();
1079	  } finally {
1080	    releaseLock(dir);
1081	  }
1082	}
1083	
1084	/**
1085	 * 把三个业务存储的新内容作为一次恢复提交。调用方已持有目录锁。
1086	 *
1087	 * 阶段:
1088	 *  1. preparing:写全部新内容到临时文件,再原子写日志。失败或中断都不影响
1089	 *     现有业务文件(此阶段中断下次可前滚或回滚)。
1090	 *  2. committing:整体换名(旧文件移为备份,新文件换入)。中断只能前滚。
1091	 *  3. 受控失败:先置 rolling-back(此后只能还原旧库),再幂等回滚。
1092	 *  4. 成功:置 done 并清理日志与旧备份。
1093	 */
1094	function commitRestore(dir: string, files: Array<{ path: string; body: string }>): void {
1095	  const journalPath = join(dir, JOURNAL_NAME);
1096	  const journal: Journal = {
1097	    phase: 'preparing',
1098	    files: files.map((f) => ({ name: basename(f.path), hadOld: existsSync(f.path) })),
1099	  };
1100	
1101	  // 阶段一:准备。此阶段失败不改变业务文件;不留日志(下次按残留清理)。
1102	  try {
1103	    for (const f of files) {
1104	      writeFileSync(f.path + NEW_SUFFIX, f.body, 'utf8');
1105	    }
1106	    writeJournalPhase(dir, journal, 'preparing');
1107	  } catch (e) {
1108	    for (const f of files) {
1109	      try {
1110	        if (existsSync(f.path + NEW_SUFFIX)) rmSync(f.path + NEW_SUFFIX);
1111	      } catch {
1112	        // 清理失败不掩盖原始错误;无日志,残留由下次启动清理。
1113	      }
1114	    }
1115	    throw new StoreError(`cannot prepare restore in ${dir}: ${(e as Error).message}; nothing was changed`);
1116	  }
1117	
1118	  // 阶段二:整体换名提交。
1119	  try {
1120	    writeJournalPhase(dir, journal, 'committing');
1121	    for (const f of journal.files) {
1122	      const target = join(dir, f.name);
1123	      if (existsSync(target)) {
1124	        renameSync(target, target + OLD_SUFFIX);
1125	      }
1126	    }
1127	    for (const f of journal.files) {
1128	      const target = join(dir, f.name);
1129	      renameSync(target + NEW_SUFFIX, target);
1130	    }
1131	  } catch (e) {
1132	    // 受控失败:进入 rolling-back 后只能继续还原完整旧库(幂等,可中断)。
1133	    try {
1134	      writeJournalPhase(dir, journal, 'rolling-back');
1135	    } catch (we) {
1136	      throw new StoreError(
1137	        `restore failed (${(e as Error).message}) and the rollback could not be started ` +
1138	          `(${ (we as Error).message}); data directory ${dir} keeps its restore materials - ` +
1139	          `run any meterwatch command again to continue the rollback`,
1140	      );
1141	    }
1142	    try {
1143	      rollbackPass(dir, journal);
1144	      rollbackCleanup(dir, journal);
1145	    } catch (re) {
1146	      throw new StoreError(
1147	        `restore failed (${(e as Error).message}); rollback is in progress and could not finish ` +
1148	          `(${ (re as Error).message}); data directory ${dir} keeps all materials needed to continue - ` +
1149	          `run any meterwatch command again to finish restoring the previous state`,
1150	      );
1151	    }
1152	    throw new StoreError(`restore failed: ${(e as Error).message}; previous state restored`);
1153	  }
1154	
1155	  // 阶段三:提交已落地,记录完成并清理备份。清理失败不影响快照一致性,
1156	  // 但仍作为错误上报;下次启动会完成收尾。
1157	  try {
1158	    writeJournalPhase(dir, journal, 'done');
1159	    rollForwardCleanup(dir, journal);
1160	  } catch (e) {
1161	    throw new StoreError(
1162	      `snapshot state was committed but post-commit cleanup failed: ${(e as Error).message}; ` +
1163	        `run any meterwatch command again to finish cleanup`,
1164	    );
1165	  }
1166	}
1167	
1168	/** 各存储内容汇总的一行数量报告。 */
1169	function countsReport(data: StoreData, alerts: AlertState, groups: Group[]): string {
1170	  const versions = groups.reduce((n, g) => n + g.versions.length, 0);
1171	  return (
1172	    `${data.readings.length} reading(s), ${data.corrections.length} correction(s), ` +
1173	    `${data.undos.length} undo(s), ${groups.length} group(s) (${versions} member version(s)), ` +
1174	    `${alerts.rules.length} rule(s), ${alerts.alerts.length} alert(s)`
1175	  );
1176	}
1177	
1178	/**
1179	 * 导出全库快照。在目录操作权与自恢复协调之内运行(见
1180	 * withDirectoryCoordination):只读取业务存储,不改写业务数据;输出文件必须
1181	 * 位于数据目录之外且不得已存在。返回进程退出码。
1182	 */
1183	export function cmdBackup(outPath: string): number {
1184	  const dir = dataDirPath();
1185	  if (isInsideDir(dir, outPath)) {
1186	    err(`snapshot file '${outPath}' must be located outside the data directory ${dir}`);
1187	    return 2;
1188	  }
1189	
1190	  let data: StoreData;
1191	  let alerts: AlertState;
1192	  let groups: Group[];
1193	  try {
1194	    data = loadData(dataFilePath());
1195	    alerts = loadAlertState(alertFilePath());
1196	    groups = loadGroups(groupFilePath());
1197	  } catch (e) {
1198	    if (e instanceof StoreError) {
1199	      err(e.message);
1200	      return 1;
1201	    }
1202	    throw e;
1203	  }
1204	
1205	  const problems = validateStores(data, alerts, groups);
1206	  if (problems.length > 0) {
1207	    for (const p of problems) err(p);
1208	    err(`backup rejected: ${problems.length} consistency problem(s); no snapshot was written`);
1209	    return 1;
1210	  }
1211	
1212	  const payload = {
1213	    readings: serializeStoreData(data),
1214	    alerts: serializeAlertState(alerts),
1215	    groups: serializeGroups(groups),
1216	  };
1217	  const checksum = createHash('sha256').update(JSON.stringify(payload), 'utf8').digest('hex');
1218	  const body =
1219	    JSON.stringify(
1220	      {
1221	        format: SNAPSHOT_FORMAT,
1222	        version: SNAPSHOT_VERSION,
1223	        checksum: `sha256:${checksum}`,
1224	        payload,
1225	      },
1226	      null,
1227	      2,
1228	    ) + '\n';
1229	
1230	  // 先写临时文件,再原子链接为最终名:已存在的输出拒绝覆盖,失败不留下
1231	  // 可被当作成功快照的输出。
1232	  const out = resolve(outPath);
1233	  const tmp = `${out}.tmp-${process.pid}`;
1234	  try {
1235	    writeFileSync(tmp, body, 'utf8');
1236	    linkSync(tmp, out);
1237	  } catch (e) {
1238	    if ((e as NodeJS.ErrnoException).code === 'EEXIST') {
1239	      err(`output file '${outPath}' already exists; refusing to overwrite`);
1240	    } else {
1241	      err(`cannot write snapshot '${outPath}': ${(e as Error).message}`);
1242	    }
1243	    return 1;
1244	  } finally {
1245	    try {
1246	      rmSync(tmp);
1247	    } catch {
1248	      // 临时文件可能未创建;清理失败不影响结果。
1249	    }
1250	  }
1251	
1252	  console.log(`snapshot written to '${outPath}': ${countsReport(data, alerts, groups)}`);
1253	  return 0;
1254	}
1255	
1256	/**
1257	 * 读取并校验快照:格式标识、格式版本、SHA-256 完整性、三个业务存储的结构
1258	 * 与关联(沿用旧快照兼容规则)。任一失败打印原因并返回 null,不改动任何
1259	 * 文件;成功返回解析后的三个存储。
1260	 */
1261	function loadSnapshotStores(
1262	  snapshotPath: string,
1263	): { data: StoreData; alerts: AlertState; groups: Group[] } | null {
1264	  let text: string;
1265	  try {
1266	    text = readFileSync(resolve(snapshotPath), 'utf8');
1267	  } catch (e) {
1268	    err(`cannot read snapshot '${snapshotPath}': ${(e as Error).message}`);
1269	    return null;
1270	  }
1271	  let envelope: unknown;
1272	  try {
1273	    envelope = JSON.parse(text);
1274	  } catch {
1275	    err(`snapshot '${snapshotPath}' is corrupted (invalid JSON or truncated); nothing was restored`);
1276	    return null;
1277	  }
1278	  const env = envelope as Record<string, unknown>;
1279	  if (env === null || typeof env !== 'object' || env.format !== SNAPSHOT_FORMAT) {
1280	    err(`snapshot '${snapshotPath}' is not a meterwatch snapshot; nothing was restored`);
1281	    return null;
1282	  }
1283	  if (env.version !== SNAPSHOT_VERSION) {
1284	    err(
1285	      `snapshot '${snapshotPath}' has unsupported format version ${String(env.version)} ` +
1286	        `(this build supports version ${SNAPSHOT_VERSION}); nothing was restored`,
1287	    );
1288	    return null;
1289	  }
1290	  const payloadText = JSON.stringify(env.payload) ?? '';
1291	  const checksum = createHash('sha256').update(payloadText, 'utf8').digest('hex');
1292	  if (typeof env.checksum !== 'string' || env.checksum !== `sha256:${checksum}`) {
1293	    err(`snapshot '${snapshotPath}' failed its integrity check; nothing was restored`);
1294	    return null;
1295	  }
1296	
1297	  const payload = env.payload as Record<string, unknown>;
1298	  let data: StoreData;
1299	  let alerts: AlertState;
1300	  let groups: Group[];
1301	  try {
1302	    data = parseStoreData(payload?.readings, `snapshot '${snapshotPath}' readings store`);
1303	    alerts = parseAlertState(payload?.alerts, `snapshot '${snapshotPath}' alerts store`);
1304	    groups = parseGroups(payload?.groups, `snapshot '${snapshotPath}' groups store`);
1305	  } catch (e) {
1306	    if (e instanceof StoreError) {
1307	      err(`${e.message}; nothing was restored`);
1308	      return null;
1309	    }
1310	    throw e;
1311	  }
1312	  const problems = validateStores(data, alerts, groups);
1313	  if (problems.length > 0) {
1314	    for (const p of problems) err(p);
1315	    err(`snapshot '${snapshotPath}' has ${problems.length} consistency problem(s); nothing was restored`);
1316	    return null;
1317	  }
1318	  return { data, alerts, groups };
1319	}
1320	
1321	/** 三个业务存储的目标文件内容(与快照解析结果一致,空部分序列化为空状态)。 */
1322	function storeBodies(loaded: {
1323	  data: StoreData;
1324	  alerts: AlertState;
1325	  groups: Group[];
1326	}): Array<{ path: string; body: string }> {
1327	  return [
1328	    { path: dataFilePath(), body: JSON.stringify(serializeStoreData(loaded.data), null, 2) + '\n' },
1329	    { path: alertFilePath(), body: JSON.stringify(serializeAlertState(loaded.alerts), null, 2) + '\n' },
1330	    { path: groupFilePath(), body: JSON.stringify(serializeGroups(loaded.groups), null, 2) + '\n' },
1331	  ];
1332	}
1333	
1334	/**
1335	 * 从快照整库恢复。在目录操作权与自恢复协调之内运行:协调完成后才读取并
1336	 * 校验快照(故损坏的当前库不影响恢复,恢复不以解析旧库为前提)。快照须通过
1337	 * 格式版本与完整性校验,且三个业务存储的结构与关联一致,否则不开始替换。
1338	 * 成功后业务状态完全等于快照。返回进程退出码。
1339	 */
1340	export function cmdRestore(snapshotPath: string): number {
1341	  const dir = dataDirPath();
1342	  if (isInsideDir(dir, snapshotPath)) {
1343	    err(`snapshot file '${snapshotPath}' must be located outside the data directory ${dir}`);
1344	    return 2;
1345	  }
1346	
1347	  const loaded = loadSnapshotStores(snapshotPath);
1348	  if (loaded === null) return 1;
1349	
1350	  // 快照校验全部通过后才开始替换;调用方已持有目录操作权。
1351	  try {
1352	    commitRestore(dir, storeBodies(loaded));
1353	  } catch (e) {
1354	    if (e instanceof StoreError) {
1355	      err(e.message);
1356	      return 1;
1357	    }
1358	    throw e;
1359	  }
1360	
1361	  console.log(`restored from snapshot '${snapshotPath}': ${countsReport(loaded.data, loaded.alerts, loaded.groups)}`);
1362	  return 0;
1363	}
1364	
1365	/**
1366	 * 显式快照救援:放弃无法可靠续接的旧事务,留存原始材料后整库替换为快照。
1367	 * 在救援目录协调之内运行(见 withRescueCoordination):不解析当前库与旧
1368	 * 日志,三个业务文件损坏、缺失或混杂均可。快照校验失败(返回 1)或参数
1369	 * 非法(返回 2)时不改动原库及旧事务材料。成功返回 0,三个存储整体等于
1370	 * 快照,空部分清除原数据,不自动评估。返回进程退出码。
1371	 */
1372	export function cmdRescue(snapshotPath: string): number {
1373	  const dir = dataDirPath();
1374	  if (isInsideDir(dir, snapshotPath)) {
1375	    err(`snapshot file '${snapshotPath}' must be located outside the data directory ${dir}`);
1376	    return 2;
1377	  }
1378	
1379	  const loaded = loadSnapshotStores(snapshotPath);
1380	  if (loaded === null) return 1;
1381	
1382	  let preservedDir: string;
1383	  try {
1384	    preservedDir = performRescue(dir, storeBodies(loaded));
1385	  } catch (e) {
1386	    if (e instanceof StoreError) {
1387	      err(e.message);
1388	      return 1;
1389	    }
1390	    throw e;
1391	  }
1392	
1393	  console.log(`rescued from snapshot '${snapshotPath}': ${countsReport(loaded.data, loaded.alerts, loaded.groups)}`);
1394	  console.log(
1395	    `pre-rescue state preserved in '${join(dir, preservedDir)}' ` +
1396	      `(original bytes and missing-state of the previous stores and restore materials; kept, not cleaned automatically)`,
1397	  );
1398	  return 0;
1399	}
