481	
482	    // 3) 重复确认:只记一次 acknowledged 事件。
483	    r = run(dir, ['ack', 'alert-1']);
484	    check(S, r.code === 0 && /acknowledged/.test(r.out), `first ack rc=${r.code}`);
485	    r = run(dir, ['ack', 'alert-1']);
486	    check(S, r.code === 0 && /already acknowledged; unchanged/.test(r.out), 'duplicate ack unchanged');
487	    state = readJson(dir, 'alerts.json');
488	    check(S, state.alerts[0].acknowledged === true &&
489	      state.alerts[0].events.filter((e) => e.type === 'acknowledged').length === 1, 'exactly one ack event');
490	
491	    // 4) 修正(跨进程)把周一终点读数 2.000 -> 0.500,使周一 NR=0.500(正常)。
492	    r = run(dir, ['correct', '--request', 'REQ-A',
493	      '--item', '--device', 'm', '--at', '2026-01-06T00:00:00Z', '--expect', '2.000', '--set', '0.500']);
494	    check(S, r.code === 0 && /1 reading\(s\) changed/.test(r.out), `correct rc=${r.code} ${r.err}`);
495	    // 跨进程重放同一修正:不再次改值、不增历史。
496	    r = run(dir, ['correct', '--request', 'REQ-A',
497	      '--item', '--device', 'm', '--at', '2026-01-06T00:00:00Z', '--expect', '2.000', '--set', '0.500']);
498	    check(S, r.code === 0, `replay correct rc=${r.code}`);
499	    let data = readJson(dir, 'readings.json');
