1088	    check(S, r.code === 1 && /locked by another live/.test(r.err), `locked dir rc=${r.code}: ${r.err}`);
1089	    check(S, readFileSync(join(dir, 'restore.journal'), 'utf8') === junkJournal, 'locked: materials untouched');
1090	    rmSync(join(dir, 'meterwatch.lock'));
1091	
1092	    // 显式救援成功:三个存储整体等于快照,旧事务材料从活动位置移除。
1093	    r = run(dir, ['rescue', snap]);
1094	    check(S, r.code === 0 && /rescued from snapshot/.test(r.out), `rescue rc=${r.code} ${r.err}`);
1095	    check(S, /pre-rescue state preserved in '[^']*rescue-preserved-1'/.test(r.out),
1096	      `rescue reports preserved location:\n${r.out}`);
1097	    const restored = readJson(dir, 'readings.json');
1098	    check(S, restored.readings.length === 2 && restored.corrections.length === 1 &&
1099	      restored.corrections[0].requestId === 'REQ1',
1100	    'stores wholly equal snapshot (readings + correction history)');
1101	    check(S, !existsSync(join(dir, 'restore.journal')) &&
1102	      !existsSync(join(dir, 'readings.json.restore-old')) &&
1103	      !existsSync(join(dir, 'groups.json.restore-new')),
1104	    'abandoned transaction materials removed from live locations');
1105	
1106	    // 留存完整:原始字节与缺失状态,且不按坏日志里的文件名操作。
1107	    const p1 = join(dir, 'rescue-preserved-1');
1108	    check(S, readFileSync(join(p1, 'restore.journal'), 'utf8') === junkJournal, 'preserved journal bytes');
1109	    check(S, readFileSync(join(p1, 'readings.json.restore-old'), 'utf8') === 'junk-old',
1110	      'preserved .restore-old bytes');
1111	    check(S, readFileSync(join(p1, 'groups.json.restore-new'), 'utf8') === 'junk-new',
1112	      'preserved .restore-new bytes');
1113	    check(S, readFileSync(join(p1, 'alerts.json'), 'utf8') === 'corrupt-business',
1114	      'preserved corrupt business bytes');
1115	    check(S, !existsSync(join(p1, 'alerts.json.restore-old')), 'missing-state preserved as absence');
1116	    const manifest = JSON.parse(readFileSync(join(p1, 'rescue-manifest.json'), 'utf8'));
1117	    check(S, manifest.preserved.length === 10 &&
1118	      manifest.preserved.find((e) => e.name === 'alerts.json.restore-old').hadOld === false &&
1119	      manifest.preserved.find((e) => e.name === 'restore.journal').hadOld === true,
1120	    'manifest records raw missing-state for the fixed name set');
1121	
1122	    // 业务可用:精确读数、修正重放返回原成功结果、规则与分组历史可用。
1123	    r = run(dir, ['readings']);
1124	    check(S, r.code === 0 && /3\.000/.test(r.out), `readings usable after rescue:\n${r.out}`);
1125	    r = run(dir, ['correct', '--request', 'REQ1',
1126	      '--item', '--device', 'm', '--at', '2026-01-06T00:00:00Z', '--expect', '2.000', '--set', '3.000']);
1127	    check(S, r.code === 0 && /committed: 1 item\(s\), 1 reading\(s\) changed/.test(r.out),
1128	      `correction replay returns the original recorded result:\n${r.out}`);
1129	    r = run(dir, ['rule', 'list']);
1130	    check(S, r.code === 0 && /\bnr\b/.test(r.out), `rules usable after rescue:\n${r.out}`);
1131	    r = run(dir, ['group', 'history', '--id', 'g']);
1132	    check(S, r.code === 0 && /g/.test(r.out), `group history usable after rescue:\n${r.out}`);
1133	
1134	    // 留存材料不被启动或后续命令自动清理。
1135	    check(S, existsSync(p1) && existsSync(join(p1, 'restore.journal')),
1136	      'preserved materials are not auto-cleaned by later commands');
1137	
1138	    // 重复救援(业务文件缺失 + 日志再次损坏):序号递增,不丢材料、不改写历史。
1139	    rmSync(join(dir, 'groups.json'));
1140	    write(join(dir, 'restore.journal'), 'garbage-again');
1141	    r = run(dir, ['rescue', snap]);
1142	    check(S, r.code === 0, `second rescue rc=${r.code} ${r.err}`);
1143	    check(S, existsSync(join(dir, 'rescue-preserved-2')) && existsSync(join(p1, 'restore.journal')),
1144	      'repeated rescue keeps earlier materials');
1145	    check(S, !existsSync(join(dir, 'rescue-preserved-2', 'groups.json')),
1146	      'second preservation records the missing business file');
1147	    r = run(dir, ['group', 'history', '--id', 'g']);
1148	    check(S, r.code === 0, `business usable after second rescue:\n${r.out}`);
1149	  } finally {
1150	    rmSync(dir, { recursive: true, force: true });
1151	    rmSync(snapDir, { recursive: true, force: true });
1152	  }
1153	}
1154	
1155	// R2:救援在留存/替换/回退中被中断后,任一命令启动先续接为完整快照或完整退回
1156	// 救援前状态,不开放混合库;确定回退后不得改向,退回后普通命令继续拒绝。
1157	function scenarioRescueInterrupted() {
1158	  const S = 'R2 interrupted rescue continuation (preserving/committing/rolling-back)';
1159	  const mkJournal = (phase, preservedDir, preserved) => JSON.stringify({
1160	    format: 'meterwatch-rescue-journal', version: 1, phase, preservedDir,
1161	    stores: ['readings.json', 'alerts.json', 'groups.json'], preserved,
1162	  }, null, 2) + '\n';
1163	  const fixedRecord = (d) => {
1164	    const names = [];
1165	    for (const n of ['readings.json', 'alerts.json', 'groups.json']) {
1166	      names.push(n, `${n}.restore-old`, `${n}.restore-new`);
1167	    }
1168	    names.push('restore.journal');
1169	    return names.map((name) => ({ name, hadOld: existsSync(join(d, name)) }));
1170	  };
1171	
1172	  // (a) preserving 阶段中断:替换尚未开始,退回救援前状态,业务文件不变。
1173	  const dirA = makeDataDir();
1174	  try {
1175	    write(join(dirA, 'r.csv'), 'device,time,reading\na,2026-01-05T00:00:00Z,1.000\n');
1176	    let r = run(dirA, ['import', 'r.csv']);
1177	    check(S, r.code === 0, `A import rc=${r.code} ${r.err}`);
1178	    const before = storeSnapshot(dirA);
1179	    write(join(dirA, 'readings.json.rescue-new'), 'junk-new');
1180	    write(join(dirA, 'alerts.json.rescue-new'), 'junk-new');
1181	    write(join(dirA, 'groups.json.rescue-new'), 'junk-new');
1182	    mkdirSync(join(dirA, 'rescue-preserved-1')); // 部分留存(中断)
1183	    write(join(dirA, 'rescue.journal'), mkJournal('preserving', 'rescue-preserved-1', fixedRecord(dirA)));
1184	    r = run(dirA, ['readings']);
1185	    check(S, r.code === 0 && /device: a/.test(r.out),
1186	      `A: preserving interruption must roll back to pre-rescue state: rc=${r.code} ${r.err}`);
1187	    check(S, sameSnapshot(before, storeSnapshot(dirA)) === null, 'A: business files untouched');
1188	    check(S, !existsSync(join(dirA, 'rescue.journal')) && !existsSync(join(dirA, 'readings.json.rescue-new')),
1189	      'A: rescue temps and journal cleaned');
1190	    check(S, existsSync(join(dirA, 'rescue-preserved-1')), 'A: preserved dir is not auto-cleaned');
1191	  } finally {
1192	    rmSync(dirA, { recursive: true, force: true });
1193	  }
1194	
1195	  // (b) committing 阶段中断:只能前滚为完整快照,旧事务材料随收尾移除。
1196	  const dirB = makeDataDir();
1197	  const dirC = makeDataDir();
1198	  try {
1199	    write(join(dirB, 'r.csv'), 'device,time,reading\nm2,2026-01-05T00:00:00Z,5.000\n');
1200	    let r = run(dirB, ['import', 'r.csv']);
1201	    check(S, r.code === 0, `B import rc=${r.code} ${r.err}`);
1202	    r = run(dirB, ['rule', 'create', '--id', 'd1', '--device', 'm2', '--threshold', '1']);
1203	    check(S, r.code === 0, `B rule rc=${r.code} ${r.err}`);
1204	    r = run(dirB, ['group', 'configure', '--id', 'gb', '--at', '2026-01-01T00:00:00Z', '--device', 'm2']);
1205	    check(S, r.code === 0, `B group rc=${r.code} ${r.err}`);
1206	    write(join(dirC, 'r.csv'), 'device,time,reading\nx,2026-01-05T00:00:00Z,1.000\n');
1207	    r = run(dirC, ['import', 'r.csv']);
1208	    check(S, r.code === 0, `C import rc=${r.code} ${r.err}`);
1209	    // 损坏旧事务材料 + 提交中途的现场:新内容已在 *.rescue-new。
1210	    write(join(dirC, 'restore.journal'), 'corrupt');
1211	    write(join(dirC, 'readings.json.restore-old'), 'junk');
1212	    for (const n of ['readings.json', 'alerts.json', 'groups.json']) {
1213	      copyFileSync(join(dirB, n), join(dirC, `${n}.rescue-new`));
1214	    }
1215	    mkdirSync(join(dirC, 'rescue-preserved-1'));
1216	    write(join(dirC, 'rescue.journal'), mkJournal('committing', 'rescue-preserved-1', fixedRecord(dirC)));
1217	    r = run(dirC, ['readings']);
1218	    check(S, r.code === 0 && /device: m2/.test(r.out) && !/device: x/.test(r.out),
1219	      `B: interrupted commit must complete to the full snapshot:\n${r.out}\n${r.err}`);
1220	    check(S, !existsSync(join(dirC, 'rescue.journal')) && !existsSync(join(dirC, 'restore.journal')) &&
1221	      !existsSync(join(dirC, 'readings.json.restore-old')) && !existsSync(join(dirC, 'readings.json.rescue-new')),
1222	    'B: journals, temps and abandoned materials cleaned after commit');
1223	    check(S, existsSync(join(dirC, 'rescue-preserved-1')), 'B: preserved dir kept');
1224	    r = run(dirC, ['rule', 'list']);
1225	    check(S, r.code === 0 && /\bd1\b/.test(r.out), `B: rules from snapshot usable:\n${r.out}`);
1226	  } finally {
1227	    rmSync(dirB, { recursive: true, force: true });
1228	    rmSync(dirC, { recursive: true, force: true });
1229	  }
1230	
1231	  // (c) rolling-back 阶段中断:只能继续还原救援前状态;原损坏日志恢复到位后
1232	  // 普通命令继续拒绝,仍可显式救援。
1233	  const dirD = makeDataDir();
1234	  const snapDir = makeDataDir();
1235	  try {
1236	    write(join(dirD, 'r.csv'), 'device,time,reading\ny,2026-01-05T00:00:00Z,7.000\n');
1237	    let r = run(dirD, ['import', 'r.csv']);
1238	    check(S, r.code === 0, `D import rc=${r.code} ${r.err}`);
1239	    const snap = join(snapDir, 'snap.json');
1240	    r = run(dirD, ['backup', snap]);
1241	    check(S, r.code === 0, `D backup rc=${r.code} ${r.err}`);
1242	    const origReadings = readFileSync(join(dirD, 'readings.json'), 'utf8');
1243	    // 回退中途的现场:业务文件已被换入的新内容替换,旧事务材料已被移除。
1244	    write(join(dirD, 'readings.json'), '{"readings":[],"corrections":[],"undos":[]}\n');
1245	    mkdirSync(join(dirD, 'rescue-preserved-1'));
1246	    write(join(dirD, 'rescue-preserved-1', 'readings.json'), origReadings);
1247	    write(join(dirD, 'rescue-preserved-1', 'restore.journal'), 'corrupt-journal');
1248	    const record = [
1249	      { name: 'readings.json', hadOld: true },
1250	      { name: 'readings.json.restore-old', hadOld: false },
1251	      { name: 'readings.json.restore-new', hadOld: false },
1252	      { name: 'alerts.json', hadOld: false },
1253	      { name: 'alerts.json.restore-old', hadOld: false },
1254	      { name: 'alerts.json.restore-new', hadOld: false },
1255	      { name: 'groups.json', hadOld: false },
1256	      { name: 'groups.json.restore-old', hadOld: false },
1257	      { name: 'groups.json.restore-new', hadOld: false },
1258	      { name: 'restore.journal', hadOld: true },
1259	    ];
1260	    write(join(dirD, 'rescue.journal'), mkJournal('rolling-back', 'rescue-preserved-1', record));
1261	    r = run(dirD, ['readings']);
1262	    check(S, r.code === 1 && /restore journal/.test(r.err),
1263	      `C: after rollback the restored corrupt journal must keep refusing: rc=${r.code}\n${r.out}`);
1264	    check(S, readFileSync(join(dirD, 'readings.json'), 'utf8') === origReadings,
1265	      'C: pre-rescue business bytes restored');
1266	    check(S, readFileSync(join(dirD, 'restore.journal'), 'utf8') === 'corrupt-journal',
1267	      'C: corrupt journal restored in place');
1268	    check(S, !existsSync(join(dirD, 'rescue.journal')), 'C: rescue journal removed after rollback');
1269	    check(S, existsSync(join(dirD, 'rescue-preserved-1')), 'C: preserved materials kept');
1270	    // 显式救援仍可用,成功后业务恢复。
1271	    r = run(dirD, ['rescue', snap]);
1272	    check(S, r.code === 0, `C: explicit rescue after rollback rc=${r.code} ${r.err}`);
1273	    r = run(dirD, ['readings']);
1274	    check(S, r.code === 0 && /device: y/.test(r.out), `C: business usable after rescue:\n${r.out}`);
1275	  } finally {
1276	    rmSync(dirD, { recursive: true, force: true });
1277	    rmSync(snapDir, { recursive: true, force: true });
1278	  }
1279	}
1280	
1281	// R3:救援替换阶段受控失败 → 确定回退不得改向;回退受阻(文件锁定)时保留全部
1282	// 材料并阻止业务,故障排除后任一命令续接还原救援前状态,普通命令继续拒绝。
1283	function scenarioRescueFailureRollback() {
1284	  const S = 'R3 rescue commit failure rolls back; blocked rollback keeps materials';
1285	  const dir = makeDataDir();
1286	  const snapDir = makeDataDir();
1287	  try {
1288	    write(join(dir, 'r.csv'), 'device,time,reading\nz,2026-01-05T00:00:00Z,9.000\n');
1289	    let r = run(dir, ['import', 'r.csv']);
1290	    check(S, r.code === 0, `import rc=${r.code} ${r.err}`);
1291	    const snap = join(snapDir, 'snap.json');
1292	    r = run(dir, ['backup', snap]);
1293	    check(S, r.code === 0, `backup rc=${r.code} ${r.err}`);
1294	    const origReadings = readFileSync(join(dir, 'readings.json'), 'utf8');
1295	    write(join(dir, 'restore.journal'), 'corrupt-journal');
1296	
1297	    // 可控本地故障:锁定业务文件,使替换与回滚的删除都失败。
1298	    const readingsPath = join(dir, 'readings.json');
1299	    execFileSync('chflags', ['uchg', readingsPath]);
1300	    try {
1301	      r = run(dir, ['rescue', snap]);
1302	      check(S, r.code === 1 && /keeps all materials|keeps its rescue materials/.test(r.err),
1303	        `rescue with blocked rollback must fail rc=1 and keep materials: rc=${r.code} ${r.err}`);
1304	      // 材料全部保留:救援日志(rolling-back)、新临时、留存目录、原损坏日志。
1305	      const rj = readJson(dir, 'rescue.journal');
1306	      check(S, rj !== null && rj.phase === 'rolling-back',
1307	        `rescue journal must pin rolling-back (no direction change): ${JSON.stringify(rj)}`);
1308	      check(S, existsSync(join(dir, 'readings.json.rescue-new')), 'rescue temp kept');
1309	      check(S, existsSync(join(dir, 'rescue-preserved-1', 'readings.json')), 'preserved copy kept');
1310	      check(S, readFileSync(join(dir, 'restore.journal'), 'utf8') === 'corrupt-journal',
1311	        'old corrupt journal untouched');
1312	      check(S, readFileSync(readingsPath, 'utf8') === origReadings, 'business file untouched');
1313	      // 故障未排除时任一命令启动仍受阻,不开放混合库。
1314	      r = run(dir, ['readings']);
1315	      check(S, r.code === 1 && /cannot complete interrupted rescue/.test(r.err),
1316	        `startup must stay blocked while rollback is stuck: rc=${r.code}`);
1317	    } finally {
1318	      execFileSync('chflags', ['nouchg', readingsPath]);
1319	    }
1320	    // 故障排除后任一命令续接回退:还原救援前状态(含原损坏日志),普通命令继续拒绝。
1321	    r = run(dir, ['readings']);
1322	    check(S, r.code === 1 && /restore journal/.test(r.err),
1323	      `after rollback the restored corrupt journal keeps refusing: rc=${r.code}`);
1324	    check(S, readFileSync(readingsPath, 'utf8') === origReadings, 'pre-rescue business bytes restored');
1325	    check(S, readFileSync(join(dir, 'restore.journal'), 'utf8') === 'corrupt-journal',
1326	      'pre-rescue corrupt journal restored');
1327	    check(S, !existsSync(join(dir, 'rescue.journal')) && !existsSync(join(dir, 'readings.json.rescue-new')),
1328	      'rescue journal and temps cleaned after rollback');
1329	    check(S, existsSync(join(dir, 'rescue-preserved-1')), 'preserved materials survive rollback');
1330	    // 显式救援仍可用并成功。
1331	    r = run(dir, ['rescue', snap]);
1332	    check(S, r.code === 0, `rescue after fault cleared rc=${r.code} ${r.err}`);
1333	    r = run(dir, ['readings']);
1334	    check(S, r.code === 0 && /device: z/.test(r.out), `business usable after rescue:\n${r.out}`);
1335	  } finally {
1336	    try { execFileSync('chflags', ['nouchg', join(dir, 'readings.json')]); } catch { /* may not exist */ }
1337	    rmSync(dir, { recursive: true, force: true });
1338	    rmSync(snapDir, { recursive: true, force: true });
1339	  }
1340	}
1341	
1342	const scenarios = [
1343	  scenarioS1,
1344	  scenarioDst,
1345	  scenarioS2,
1346	  scenarioNoCoverage,
1347	  scenarioNoRecoverOnUndecidable,
1348	  scenarioBadWeekday,
1349	  scenarioLifecycle,
1350	  scenarioWriteFailure,
1351	  scenarioExceptions,
1352	  scenarioExceptionParsing,
1353	  scenarioExceptionPersistence,
1354	  scenarioExceptionDst,
1355	  scenarioRescue,
1356	  scenarioRescueInterrupted,
1357	  scenarioRescueFailureRollback,
1358	];
1359	
1360	for (const sc of scenarios) {
1361	  try {
1362	    sc();
1363	  } catch (e) {
1364	    failures.push(`[${sc.name}] harness error: ${e?.stack ?? e}`);
1365	  }
1366	}
1367	
1368	if (failures.length > 0) {
1369	  console.error(`\nFAIL: ${failures.length} assertion(s) failed, ${passed} passed`);
1370	  for (const f of failures) console.error(`  - ${f}`);
1371	  process.exit(1);
1372	}
1373	console.log(`PASS: all ${passed} assertions across ${scenarios.length} scenarios`);
