/** 救援回滚收尾:删除新临时文件与救援日志。留存目录保留,不自动清理。 */
function rescueRollbackCleanup(dir: string, journal: RescueJournal): void {
  removeRescueTemps(dir, journal.stores);
  rmSync(join(dir, RESCUE_JOURNAL_NAME));
}

